before.lib/receipt.ex:
defmodule SystemClock do
  def now, do: System.system_time(:second)
end
defmodule Receipt do
  @doc "Stamp a receipt with the selected clock; the system clock is the application default."
  def stamp(id, clock \\ SystemClock), do: %{id: id, issued_at: clock.now()}
end

